let p = document.querySelectorAll("p"), f = document.querySelector("form"), i = f.elements[0], b = document.querySelector("button"); b.addEventListener("click", e => { e.preventDefault(); const d = Math.floor(Math.random() * 10) + 1; let g = Number(p[1].innerHTML) || 0, v = Number(i.value); if (v === d) { g += 1; p[1].innerHTML = g; alert("Correct") } else { alert("Oops the correct answer is " + d); console.log(v) } });